<?php
namespace App\Filament\Resources\Events\Schemas;
use Filament\Forms\Components\DatePicker; use Filament\Forms\Components\DateTimePicker; use Filament\Forms\Components\Select; use Filament\Forms\Components\TextInput; use Filament\Forms\Components\Textarea; use Filament\Forms\Components\Toggle; use Filament\Schemas\Schema;
class EventForm { public static function configure(Schema $schema): Schema { return $schema->components([TextInput::make('name')->required()->maxLength(255), TextInput::make('slug')->required()->maxLength(255), DatePicker::make('starts_at')->required(), DatePicker::make('ends_at')->required(), DatePicker::make('final_payment_due_at')->required(), TextInput::make('location_name')->required(), TextInput::make('circuit_name')->required(), Textarea::make('circuit_address'), TextInput::make('hotel_name'), Textarea::make('hotel_address'), TextInput::make('bike_dropoff_location'), DateTimePicker::make('bike_dropoff_datetime'), DateTimePicker::make('return_datetime'), Textarea::make('description'), Select::make('status')->options(['draft'=>'Draft','open'=>'Open','closed'=>'Closed','completed'=>'Completed'])->required()]); } }
